export interface ApexRisk {
  id: string;
  desc: string;
  area: string;
  rating: 'Critical' | 'High' | 'Medium' | 'Low';
}

export interface UnmappedRisk extends ApexRisk {
  action: string;
}

export interface OrphanedControl {
  id: string;
  desc: string;
  area: string;
  type: string;
  owner: string;
  action: string;
}

export interface OverControlledRisk extends ApexRisk {
  count: number;
  rec: string;
}

export interface ApexMappedControl {
  id: string;
  desc: string;
  area: string;
  type: string;
}

export interface ApexRiskMap {
  byControl: Record<string, ApexRisk[]>;
  byRisk: Record<string, ApexMappedControl[]>;
}

